ALTER TABLE public.mastery_identity_settings ADD COLUMN pitching_initial_window integer, ADD COLUMN pitching_transition_at integer, ADD COLUMN pitching_later_window integer, ADD COLUMN defense_initial_window integer, ADD COLUMN defense_transition_at integer, ADD COLUMN defense_later_window integer; ALTER TABLE public.mastery_identity_settings ADD CONSTRAINT mastery_pitching_windows CHECK ((pitching_initial_window IS NULL AND pitching_transition_at IS NULL AND pitching_later_window IS NULL) OR (pitching_initial_window IS NOT NULL AND pitching_transition_at IS NOT NULL AND pitching_later_window IS NOT NULL AND pitching_initial_window>0 AND pitching_transition_at>0 AND pitching_later_window>0 AND pitching_transition_at%pitching_initial_window=0)), ADD CONSTRAINT mastery_defense_windows CHECK ((defense_initial_window IS NULL AND defense_transition_at IS NULL AND defense_later_window IS NULL) OR (defense_initial_window IS NOT NULL AND defense_transition_at IS NOT NULL AND defense_later_window IS NOT NULL AND defense_initial_window>0 AND defense_transition_at>0 AND defense_later_window>0 AND defense_transition_at%defense_initial_window=0)); COMMENT ON COLUMN public.mastery_identity_settings.pitching_initial_window IS 'Owner-adjustable BF cadence; null triplet inherits batting opportunity cadence.'; COMMENT ON COLUMN public.mastery_identity_settings.defense_initial_window IS 'Owner-adjustable fielding-chance cadence; null triplet inherits batting opportunity cadence.';